<script setup lang="ts">
// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Database picker: lists the `*.db` files in the user's Nextcloud files, keeps
// local labels/order, and selects one for unlocking. Locations are entered as
// paths (nothing here imports the Nextcloud files UI, so the bundle stays a
// single IIFE script).

import { t } from '@nextcloud/l10n';
import { onMounted, ref } from 'vue';

import type { DatabaseDescriptor } from '../storage/descriptor';
import { labelFromPath } from '../storage/descriptor';
import {
  forget,
  getLastOpenedId,
  listRemembered,
  remember,
  setLastOpenedId,
} from '../storage/registry';
import { getConfig, listDatabases, lookupDatabase } from '../storage/remote';
import { hasLegacyBase, migrateLegacyBase } from '../storage/syncBase';
import { selectDatabase } from '../state/session';

interface Entry extends DatabaseDescriptor {
  missing?: boolean;
}

type FormMode = 'existing' | 'new';

const entries = ref<Entry[]>([]);
const loading = ref(true);
const status = ref('');
const defaultFolder = ref('upm');
const lastOpenedId = ref<string | null>(null);
const mode = ref<FormMode | null>(null);
const formLabel = ref('');
const formPath = ref('');
const formBusy = ref(false);

/** Load the server list, merge it with the remembered labels, and sort. */
async function refresh(): Promise<void> {
  loading.value = true;
  status.value = '';
  try {
    const [remote, remembered, config, last] = await Promise.all([
      listDatabases(),
      listRemembered(),
      getConfig(),
      getLastOpenedId(),
    ]);
    defaultFolder.value = config.defaultFolder || 'upm';
    lastOpenedId.value = last;

    // One-time migration of the pre-Phase-9 base when it is unambiguous.
    if (remote.length === 1 && (await hasLegacyBase())) {
      await migrateLegacyBase(remote[0]!.id);
    }

    const merged = new Map<string, Entry>();
    for (const item of remembered) {
      merged.set(item.id, { id: item.id, label: item.label, path: item.path, missing: true });
    }
    for (const item of remote) {
      const previous = merged.get(item.id);
      merged.set(item.id, {
        id: item.id,
        path: item.path,
        label: previous?.label || labelFromPath(item.path),
        canWrite: item.canWrite,
        missing: false,
      });
    }

    // Databases outside the root folder are not listed by the server; verify
    // them individually so they do not show up as missing.
    await Promise.all(
      [...merged.values()]
        .filter((entry) => entry.missing === true)
        .map(async (entry) => {
          const found = await lookupDatabase(entry.path).catch(() => null);
          if (found !== null) {
            merged.set(found.id, {
              id: found.id,
              path: found.path,
              label: entry.label,
              canWrite: found.canWrite,
              missing: false,
            });
          }
        }),
    );

    entries.value = [...merged.values()].sort((a, b) => a.label.localeCompare(b.label));
  } catch {
    status.value = t('upm', 'Could not load the database list.');
  } finally {
    loading.value = false;
  }
}

/** Select a database; the unlock screen asks for its master password. */
async function open(entry: Entry): Promise<void> {
  const descriptor: DatabaseDescriptor = {
    id: entry.id,
    label: entry.label,
    path: entry.path,
    canWrite: entry.canWrite,
  };
  await remember(descriptor);
  await setLastOpenedId(descriptor.id);
  selectDatabase(descriptor);
}

/** Normalize a user-entered path; null when it is not a `*.db` location. */
function normalizePath(value: string): string | null {
  const path = value.trim().replace(/^\/+/, '');
  const segments = path.split('/');
  if (
    !/\.db$/i.test(path) ||
    segments.some((part) => part === '' || part === '.' || part === '..')
  ) {
    return null;
  }
  return path;
}

function startExisting(): void {
  mode.value = 'existing';
  status.value = '';
  formLabel.value = '';
  formPath.value = `${defaultFolder.value}/`;
}

function startNew(): void {
  mode.value = 'new';
  status.value = '';
  formLabel.value = '';
  formPath.value = `${defaultFolder.value}/new.db`;
}

function cancelForm(): void {
  mode.value = null;
  status.value = '';
}

/** Look up an existing database by path and select it. */
async function submitExisting(): Promise<void> {
  const path = normalizePath(formPath.value);
  if (path === null) {
    status.value = t('upm', 'Enter a valid path ending in .db.');
    return;
  }
  formBusy.value = true;
  try {
    const found = await lookupDatabase(path);
    if (found === null) {
      status.value = t('upm', 'No database found at that path.');
      return;
    }
    mode.value = null;
    await open({
      id: found.id,
      label: labelFromPath(found.path),
      path: found.path,
      canWrite: found.canWrite,
    });
  } catch {
    status.value = t('upm', 'Could not read that database.');
  } finally {
    formBusy.value = false;
  }
}

/** Select an unsaved database; it is written on the first save. */
function submitNew(): void {
  const path = normalizePath(formPath.value);
  if (path === null) {
    status.value = t('upm', 'Enter a valid path ending in .db.');
    return;
  }
  const label = formLabel.value.trim() || labelFromPath(path);
  mode.value = null;
  status.value = '';
  selectDatabase({ id: '', label, path });
}

/** Forget a database locally; the file itself is untouched. */
async function remove(entry: Entry): Promise<void> {
  await forget(entry.id);
  await refresh();
}

onMounted(refresh);
</script>

<template>
  <div class="upm-databases" style="max-width: 720px">
    <h2>{{ t('upm', 'Databases') }}</h2>
    <p style="opacity: 0.75">
      {{ t('upm', 'Choose a database from your files, or create a new one.') }}
    </p>

    <div style="display: flex; gap: 8px; margin-bottom: 12px">
      <button type="button" class="button primary" @click="startExisting">
        {{ t('upm', 'Add existing…') }}
      </button>
      <button type="button" class="button" @click="startNew">
        {{ t('upm', 'New database…') }}
      </button>
    </div>

    <p v-if="status" role="status">{{ status }}</p>
    <p v-if="loading">{{ t('upm', 'Loading…') }}</p>

    <form
      v-if="mode !== null"
      style="
        display: grid;
        grid-template-columns: max-content minmax(220px, 1fr);
        gap: 8px 12px;
        align-items: center;
        padding: 12px;
        margin-bottom: 12px;
        border: 1px solid var(--color-border, #ddd);
        border-radius: var(--border-radius, 4px);
      "
      @submit.prevent="mode === 'new' ? submitNew() : submitExisting()"
    >
      <template v-if="mode === 'new'">
        <label for="upm-form-label" style="text-align: right">{{ t('upm', 'Name') }}</label>
        <input
          id="upm-form-label"
          v-model="formLabel"
          type="text"
          :placeholder="t('upm', 'My database')"
          style="width: 100%; box-sizing: border-box"
        />
      </template>

      <label for="upm-form-path" style="text-align: right">{{ t('upm', 'Path') }}</label>
      <input
        id="upm-form-path"
        v-model="formPath"
        type="text"
        required
        placeholder="upm/my-passwords.db"
        style="width: 100%; box-sizing: border-box"
      />

      <div style="grid-column: 1 / -1; display: flex; gap: 8px">
        <button type="submit" class="button primary" :disabled="formBusy">
          {{ mode === 'new' ? t('upm', 'Create') : t('upm', 'Open') }}
        </button>
        <button type="button" class="button" @click="cancelForm">
          {{ t('upm', 'Cancel') }}
        </button>
      </div>
    </form>

    <ul style="list-style: none; padding: 0; margin: 16px 0 0">
      <li
        v-for="entry in entries"
        :key="entry.id"
        style="
          display: flex;
          gap: 12px;
          align-items: center;
          padding: 8px 0;
          border-bottom: 1px solid var(--color-border, #ddd);
        "
      >
        <div style="flex: 1 1 auto; min-width: 0">
          <div style="font-weight: bold">
            {{ entry.label }}
            <span v-if="entry.id === lastOpenedId" style="opacity: 0.6">·</span>
          </div>
          <div style="opacity: 0.7; overflow-wrap: anywhere">{{ entry.path }}</div>
          <div v-if="entry.missing" style="color: var(--color-error-text, #a30000)">
            {{ t('upm', 'File not found') }}
          </div>
          <div v-else-if="entry.canWrite === false" style="opacity: 0.7">
            {{ t('upm', 'Read-only') }}
          </div>
        </div>
        <button
          type="button"
          class="button primary"
          :disabled="entry.missing === true"
          @click="open(entry)"
        >
          {{ t('upm', 'Open') }}
        </button>
        <button type="button" class="button" @click="remove(entry)">
          {{ t('upm', 'Remove from list') }}
        </button>
      </li>
      <li v-if="!loading && entries.length === 0">{{ t('upm', 'No databases yet.') }}</li>
    </ul>
  </div>
</template>
